/**
 * dsh-mcp-manager servers/lifecycle 域（装载生命周期）官方日志归属与诊断文案单测。
 *
 * 判据面（每条都锚一个可改坏的点）：
 * - officialLogText：只认官方客户端这个记录名、只拼字符串参数、纯空白等于没说话；
 * - attributeOfficialLog：按 `mcp-client(<serverName>)` **全等前缀**归属——名字互为前缀的两个实例
 *   不能被包含匹配记到对方头上；前缀之后没有正文不算命中；
 * - diagnosticText：单行字段的形态收敛（折行折叠 + 按字符上限截断）与条数上限（取末 3 条并报出总数）；
 * - collectOfficialLogs：收集器只收归属本实例的、按到达顺序、stop 之后不再收、重复 stop 无害、
 *   摘除器抛错被吞（诊断面不得把一次已结算的装载改写成失败）。
 *
 * 夹具是 `test/helpers.ts` 的 `fakeLogsPort`（宿主日志面的结构形状）。本文件刻意不带 @ts-nocheck：
 * test/tsconfig.json 真实编译整个 test 树，隐式 any 会被 service-contract-wiring 判红。
 */
import { describe, expect, it } from "vitest";
import type { LogRecord, LogsPort } from "../../src/server/shared/interface.ts";
import {
  attributeOfficialLog,
  collectOfficialLogs,
  diagnosticText,
  officialLogText,
} from "../../src/server/servers/lifecycle/interface.ts";
import { fakeLogsPort } from "../helpers.ts";

/** 造一条宿主日志记录：判据只看 name 与 args，type / level 取最小形状。 */
function record(name: string, ...args: unknown[]): LogRecord {
  return { name, type: "warn", level: 2, args };
}

describe("officialLogText：官方记录名与可读文案", () => {
  it("不是 mcp-client 的记录名一律不取：域内导出器收的是全宿主日志", () => {
    expect(officialLogText(record("dsh-mcp-manager", "mcp-client(srv): 疑似"))).toBeUndefined();
  });

  it("没有字符串参数时返回 undefined：官方把可读文案放在字符串参数里", () => {
    expect(officialLogText(record("mcp-client", { code: 1 }, 42))).toBeUndefined();
    expect(officialLogText(record("mcp-client"))).toBeUndefined();
  });

  it("多段字符串参数按到达顺序拼接，非字符串参数不入文案", () => {
    expect(officialLogText(record("mcp-client", "connection", "refused", { port: 1 }))).toBe(
      "connection refused",
    );
  });

  it("纯空白等于没说话：返回 undefined 而不是空串", () => {
    expect(officialLogText(record("mcp-client", "   ", "\n\t"))).toBeUndefined();
  });
});

describe("attributeOfficialLog：按全等前缀归属", () => {
  it("命中：去掉 mcp-client(<id>) 前缀与紧随的冒号（半角 / 全角 / 空白）", () => {
    expect(attributeOfficialLog("mcp-client(id1): 连接被拒", "id1")).toBe("连接被拒");
    expect(attributeOfficialLog("mcp-client(id1)：连接被拒", "id1")).toBe("连接被拒");
    expect(attributeOfficialLog("mcp-client(id1) 连接被拒", "id1")).toBe("连接被拒");
  });

  it("id 互为前缀时不误归属：包含匹配会把 A 的错因记到 B 头上", () => {
    // 另一个实例的 id 是本 id 的前缀。
    expect(attributeOfficialLog("mcp-client(idsee): 别人的失败", "idseed")).toBeUndefined();
    // 本 id 是另一个实例 id 的前缀。
    expect(attributeOfficialLog("mcp-client(idseed): 别人的失败", "idsee")).toBeUndefined();
  });

  it("前缀出现在文案中段不算命中：归属认的是整条记录的开头", () => {
    // 官方可能转述别人的原话，包含匹配会把中段那个前缀后面的碎片当成自己的错因。
    expect(attributeOfficialLog("转述：mcp-client(id1): 连接被拒", "id1")).toBeUndefined();
  });

  it("前缀之后没有正文不算命中：只有前缀（或补冒号 / 空白）返回 undefined", () => {
    expect(attributeOfficialLog("mcp-client(id1)", "id1")).toBeUndefined();
    expect(attributeOfficialLog("mcp-client(id1):", "id1")).toBeUndefined();
    expect(attributeOfficialLog("mcp-client(id1)：   ", "id1")).toBeUndefined();
  });
});

describe("diagnosticText：状态面字段的形态收敛", () => {
  it("空数组或全空白返回 undefined：不占状态面字段", () => {
    expect(diagnosticText([])).toBeUndefined();
    expect(diagnosticText(["  ", "\n"])).toBeUndefined();
  });

  it("不超过上限时原样给出，不报条数", () => {
    expect(diagnosticText(["连接被拒", "已放弃重连"])).toBe("官方日志：连接被拒 | 已放弃重连");
  });

  it("超过 3 条取末 3 条并报出总条数：不说省略了多少，读的人会以为官方只说了这些", () => {
    expect(diagnosticText(["a", "b", "c", "d", "e"])).toBe(
      "官方日志（共 5 条，取末 3 条）：c | d | e",
    );
  });

  it("单条超上限按字符截断并带省略号，折行折叠成空格", () => {
    expect(diagnosticText(["x".repeat(300)])).toBe("官方日志：" + "x".repeat(240) + "…");
    expect(diagnosticText(["第一行\n第二行"])).toBe("官方日志：第一行 第二行");
  });
});

describe("collectOfficialLogs：一个装载窗口的收集面", () => {
  it("只收归属本实例的官方日志，按到达顺序：别的记录名 / 别的 id 一律不收", () => {
    const logs = fakeLogsPort();
    const collected = collectOfficialLogs(logs as unknown as LogsPort, "id1");

    logs.emit(record("mcp-client", "mcp-client(id1): 第一条"));
    logs.emit(record("mcp-client", "mcp-client(id2): 别人的失败"));
    logs.emit(record("dsh-mcp-manager", "mcp-client(id1): 别的插件"));
    logs.emit(record("mcp-client", "mcp-client(id1): 第二条"));

    expect(collected.lines()).toEqual(["第一条", "第二条"]);
  });

  it("stop() 摘掉导出器：之后到的官方日志不再收，重复 stop 无害", () => {
    const logs = fakeLogsPort();
    const collected = collectOfficialLogs(logs as unknown as LogsPort, "id1");
    logs.emit(record("mcp-client", "mcp-client(id1): 第一条"));

    collected.stop();
    expect(logs.captured).toBe(0);
    logs.emit(record("mcp-client", "mcp-client(id1): 第二条"));

    expect(collected.lines()).toEqual(["第一条"]);
    expect(() => collected.stop()).not.toThrow();
  });

  it("摘除器抛错被吞：诊断面不得把一次已结算的装载改写成失败", () => {
    let disposeCalls = 0;
    const logs: LogsPort = {
      capture: () => () => {
        disposeCalls += 1;
        throw new Error("宿主摘除失败");
      },
    };
    const collected = collectOfficialLogs(logs as unknown as LogsPort, "id1");

    expect(() => collected.stop()).not.toThrow();
    expect(() => collected.stop()).not.toThrow();
    expect(disposeCalls).toBe(1);
  });
});

/**
 * dsh-mcp-manager — unit：workspace 域的 (scope, name)→id 内存表（#767 S1-4a）。
 *
 * 判据锚点：同参恒同值、不同参不共享、scope 边界不产生键歧义、id 恒满足官方字符集与长度、
 * 冲突重试有界、生成器产出非法值时如实抛错、跨实例不共享（I9 实证）。
 *
 * 官方 SERVER_NAME_PATTERN 在断言里**独立抄写**一份：若拿被测实现消费的那份常量做断言，常量被
 * 改宽时两侧一起变，判据静默失效；这里额外用 source 相等把「共享层那份仍是官方口径」钉住。
 *
 * 本片全同步（id 分配不涉任何等待），没有时序假设，因此不需要 pollUntil，也不存在固定 sleep。
 */
import { describe, expect, it } from "vitest";
import { SERVER_NAME_PATTERN } from "../../src/server/shared/interface.ts";
import { makeServerIdTable } from "../../src/server/workspace/interface.ts";

/** 官方 @deepseek-ai/dsh-mcp-client 的 serverName 约束（独立抄写，防同源互证）。 */
const OFFICIAL_SERVER_NAME_PATTERN = /^[A-Za-z0-9_-]{1,32}$/;

/** 按序吐出候选值的注入生成器；`calls` 暴露调用次数，用来证明「命中已有条目不再要 id」。 */
function idSequence(values: string[]) {
  let index = 0;
  return {
    factory: () => values[Math.min(index++, values.length - 1)],
    calls: () => index,
  };
}

describe("(scope, name) → id 内存表", () => {
  it("同一 (scope, name) 恒得同一 id，且只向生成器要一次", () => {
    const seq = idSequence(["id_one"]);
    const table = makeServerIdTable({ idFactory: seq.factory });
    const first = table.idFor("/proj/a", "srv");
    expect(table.idFor("/proj/a", "srv")).toBe(first);
    expect(table.idFor("/proj/a", "srv")).toBe(first);
    expect(first).toBe("id_one");
    expect(seq.calls()).toBe(1);
  });

  it("不同 (scope, name) 取到不同 id", () => {
    const seq = idSequence(["id_a", "id_b", "id_c"]);
    const table = makeServerIdTable({ idFactory: seq.factory });
    const ids = [
      table.idFor("/proj/a", "srv"),
      table.idFor("/proj/a", "other"),
      table.idFor("/proj/b", "srv"),
    ];
    expect(new Set(ids).size).toBe(3);
  });

  it("同名不同 scope 各自成条：跨 root 同名不再互斥", () => {
    const seq = idSequence(["id_g", "id_p"]);
    const table = makeServerIdTable({ idFactory: seq.factory });
    expect(table.idFor("@global", "srv")).toBe("id_g");
    expect(table.idFor("/proj/a", "srv")).toBe("id_p");
    expect(table.has("@global", "srv")).toBe(true);
    expect(table.has("/proj/a", "srv")).toBe(true);
  });

  it("has 只反映已分配状态，不触发分配", () => {
    const seq = idSequence(["id_x"]);
    const table = makeServerIdTable({ idFactory: seq.factory });
    expect(table.has("/proj/a", "srv")).toBe(false);
    expect(seq.calls()).toBe(0);
    table.idFor("/proj/a", "srv");
    expect(table.has("/proj/a", "srv")).toBe(true);
    expect(table.has("/proj/b", "srv")).toBe(false);
    expect(seq.calls()).toBe(1);
  });

  it("scope 与 name 的边界不含分隔符歧义：常见分隔符都不改变归属", () => {
    // 实现按 scope 分表；若改成「拼成一个字符串键」，下面每种分隔符都会把两组并成同一个键。
    for (const sep of [":", "/", "|", "\u0000", " "]) {
      const seq = idSequence(["id_1", "id_2"]);
      const table = makeServerIdTable({ idFactory: seq.factory });
      expect(table.idFor("s", `x${sep}y`)).not.toBe(table.idFor(`s${sep}x`, "y"));
    }
  });

  it("id 恒满足官方模式：注入的确定性生成器", () => {
    const table = makeServerIdTable({ idFactory: () => "Fixed_ID-09" });
    const id = table.idFor("/proj/a", "srv");
    expect(id).toBe("Fixed_ID-09");
    expect(OFFICIAL_SERVER_NAME_PATTERN.test(id)).toBe(true);
    // 共享层那份是单一物理定义，必须仍是官方口径（否则 id 的准入判定会跟着漂）。
    expect(SERVER_NAME_PATTERN.source).toBe(OFFICIAL_SERVER_NAME_PATTERN.source);
  });

  it("id 恒满足官方模式：默认生成器 200 次抽取各不相同且全部合规", () => {
    const table = makeServerIdTable();
    const ids = new Set<string>();
    for (let i = 0; i < 200; i += 1) {
      const id = table.idFor("/proj/a", `srv-${i}`);
      expect(OFFICIAL_SERVER_NAME_PATTERN.test(id)).toBe(true);
      ids.add(id);
    }
    expect(ids.size).toBe(200);
  });

  it("生成器连续产出已占用的 id 时重试，直到取到未占用候选", () => {
    const seq = idSequence(["dup", "dup", "uniq"]);
    const table = makeServerIdTable({ idFactory: seq.factory });
    expect(table.idFor("/proj/a", "srv")).toBe("dup");
    expect(table.idFor("/proj/a", "other")).toBe("uniq");
    expect(seq.calls()).toBe(3);
  });

  it("冲突重试有上界：恒定冲突的生成器如实抛错且不留半条记录", () => {
    const table = makeServerIdTable({ idFactory: () => "same" });
    expect(table.idFor("/proj/a", "srv")).toBe("same");
    expect(() => table.idFor("/proj/a", "other")).toThrow(/分配失败/);
    expect(table.has("/proj/a", "other")).toBe(false);
    expect(table.idFor("/proj/a", "srv")).toBe("same");
  });

  it("生成器产出非法字符的 id 时如实抛错，不静默放行", () => {
    const table = makeServerIdTable({ idFactory: () => "bad id!" });
    expect(() => table.idFor("/proj/a", "srv")).toThrow(/SERVER_NAME_PATTERN/);
    expect(table.has("/proj/a", "srv")).toBe(false);
  });

  it("生成器返回非字符串时同样拒绝（正则会隐式字符串化并放行 undefined）", () => {
    const table = makeServerIdTable({ idFactory: () => undefined as unknown as string });
    expect(() => table.idFor("/proj/a", "srv")).toThrow(/SERVER_NAME_PATTERN/);
  });

  it("跨实例不共享：第二张表不影响第一张（I9）", () => {
    const first = makeServerIdTable({ idFactory: () => "shared_id" });
    const second = makeServerIdTable({ idFactory: () => "shared_id" });
    expect(first.idFor("/proj/a", "srv")).toBe("shared_id");
    // 第一张表已占用 shared_id；第二张表若真独立，就必须照常分配（模块级状态会让它冲突抛错）。
    expect(second.idFor("/proj/a", "other")).toBe("shared_id");
    expect(first.has("/proj/a", "other")).toBe(false);
    expect(second.has("/proj/a", "other")).toBe(true);
  });
});

/**
 * dsh-mcp-manager — unit：config 域模板预展开与 reconnect 收紧（#767 S1-1）。
 *
 * 直引域内实现文件而不经组合根：单元层是白盒面（ARCHITECTURE-METHOD §8.1），走入口会把
 * 装配顺序与端口实参一起带进用例，失败点会从「展开器写错」漂到「装配写错」。
 */
import { describe, expect, it } from "vitest";
import { expandEnv, expandServerEnv } from "../../src/server/config/impl/env/index.ts";
import { normalizeServer } from "../../src/server/config/normalize.ts";

const ENV_SET = "DSH_S11_CFG_ENV_SET";
const ENV_MISSING = "DSH_S11_CFG_ENV_MISSING";

describe("expandEnv", () => {
  process.env[ENV_SET] = "va";
  delete process.env[ENV_MISSING];

  it("已设置变量展开", () => {
    expect(expandEnv("${" + ENV_SET + "}")).toBe("va");
  });

  it("未设置变量展开为空串", () => {
    expect(expandEnv("x${" + ENV_MISSING + "}y")).toBe("xy");
  });

  it("混合展开", () => {
    expect(expandEnv("${" + ENV_SET + "}-${" + ENV_MISSING + "}")).toBe("va-");
  });

  it("无引用原样返回", () => {
    expect(expandEnv("plain")).toBe("plain");
  });

  it("非字符串 String 化", () => {
    expect(expandEnv(42)).toBe("42");
  });

  it("非法变量名不匹配替换", () => {
    expect(expandEnv("${1BAD}")).toBe("${1BAD}");
  });
});

describe("expandServerEnv", () => {
  process.env[ENV_SET] = "va";
  delete process.env[ENV_MISSING];

  it("stdio 面：env 模板展开，其余字段原样带上", () => {
    const expanded = expandServerEnv({
      name: "s",
      transport: "stdio",
      command: "cmd",
      args: ["--flag"],
      env: { A: "${" + ENV_SET + "}", B: "x${" + ENV_MISSING + "}y" },
    });
    expect(expanded.env).toEqual({ A: "va", B: "xy" });
    expect(expanded.command).toBe("cmd");
    expect(expanded.args).toEqual(["--flag"]);
  });

  it("http 面：headers 模板展开", () => {
    const expanded = expandServerEnv({
      name: "s",
      transport: "streamable-http",
      url: "http://localhost:1/mcp",
      headers: { Authorization: "Bearer ${" + ENV_SET + "}", Plain: "p" },
    });
    expect(expanded.headers).toEqual({ Authorization: "Bearer va", Plain: "p" });
  });

  it("非字符串值 String 化", () => {
    const expanded = expandServerEnv({
      name: "s",
      transport: "stdio",
      command: "c",
      env: { N: 42 as unknown as string },
    });
    expect(expanded.env).toEqual({ N: "42" });
  });

  it("无 env / headers 时不凭空造键", () => {
    const expanded = expandServerEnv({ name: "s", transport: "stdio", command: "c" });
    expect("env" in expanded).toBe(false);
    expect("headers" in expanded).toBe(false);
  });

  it("返回新对象，源配置的模板不被就地展开", () => {
    const source = {
      name: "s",
      transport: "stdio" as const,
      command: "c",
      env: { A: "${" + ENV_SET + "}" },
    };
    const expanded = expandServerEnv(source);
    expect(expanded).not.toBe(source);
    expect(expanded.env).not.toBe(source.env);
    expect(source.env.A).toBe("${" + ENV_SET + "}");
  });
});

describe("normalizeServer：reconnect 收紧", () => {
  const withReconnect = (reconnect: unknown) => ({
    name: "s",
    transport: "stdio",
    command: "c",
    reconnect,
  });

  it("未知键丢弃且不出声（归一器保持纯函数）", () => {
    const server = normalizeServer(withReconnect({ enabled: false, jitter: 1 }));
    expect(server.reconnect).toEqual({ enabled: false });
    expect(JSON.stringify(server.reconnect)).not.toContain("jitter");
  });

  it("只保留输入里写了的键，不补齐默认值", () => {
    expect(normalizeServer(withReconnect(undefined)).reconnect).toEqual({});
    expect(normalizeServer(withReconnect({ maxAttempts: 3 })).reconnect).toEqual({
      maxAttempts: 3,
    });
  });

  it("合法 4 键原样保留", () => {
    const reconnect = { enabled: true, initialDelayMs: 100, maxDelayMs: 200, maxAttempts: 3 };
    expect(normalizeServer(withReconnect(reconnect)).reconnect).toEqual(reconnect);
  });

  it("initialDelayMs > maxDelayMs 拒绝", () => {
    expect(() => normalizeServer(withReconnect({ initialDelayMs: 5000, maxDelayMs: 100 }))).toThrow(
      /initialDelayMs must be less than or equal to maxDelayMs/,
    );
  });

  it("只写 initialDelayMs 且大于默认 maxDelayMs 时拒绝（官方会先补默认值再判关系）", () => {
    // 官方 RECONNECT_DEFAULTS.maxDelayMs = 30000；只写 initialDelayMs 时它会在装载期抛，
    // 这一条守住的正是「错误不许被推迟到连接期」。
    expect(() => normalizeServer(withReconnect({ initialDelayMs: 60_000 }))).toThrow(
      /initialDelayMs must be less than or equal to maxDelayMs/,
    );
    // 两段都显式写出且关系成立时仍然放行（默认值不参与判定）。
    expect(
      normalizeServer(withReconnect({ initialDelayMs: 40_000, maxDelayMs: 50_000 })).reconnect,
    ).toEqual({ initialDelayMs: 40_000, maxDelayMs: 50_000 });
  });

  it("enabled 非布尔拒绝", () => {
    for (const enabled of ["yes", 1, null]) {
      expect(() => normalizeServer(withReconnect({ enabled }))).toThrow(
        /enabled must be a boolean/,
      );
    }
  });

  it("退避时长非正数或非有限数拒绝", () => {
    for (const initialDelayMs of [0, -1, Number.POSITIVE_INFINITY, "500"]) {
      expect(() => normalizeServer(withReconnect({ initialDelayMs }))).toThrow(/initialDelayMs/);
    }
  });

  it("maxAttempts 非正整数拒绝", () => {
    for (const maxAttempts of [0, -1, 1.5, "3"]) {
      expect(() => normalizeServer(withReconnect({ maxAttempts }))).toThrow(
        /maxAttempts must be a positive integer/,
      );
    }
  });

  it("reconnect 不是对象时拒绝", () => {
    expect(() => normalizeServer(withReconnect("nope"))).toThrow(/reconnect must be an object/);
  });
});

/**
 * dsh-mcp-manager — unit：工作空间路由域（src/workspace/，#664 阶段 4）。
 *
 * 覆盖：
 * - makeResolveRoot 基本路由（agent-less → undefined / cwd 项目 root 优先）
 * - B3 红测：空 cwd 回落 @global 含 runtime 源（runtimeRegistry 并集）
 *
 * - normalizeScope 全分支（#767 S1-5c 自 unit-transport.test.ts 迁入：被测对象是 workspace
 *   域的纯函数，且是全仓唯一覆盖点——随自研连接栈退役，原宿主文件已删）
 *
 * 其余域函数（findProjectRoot/normalizedProjectRoot/full-name）由
 * unit-manager2 / unit-middleware 既有断言面覆盖（T1：经 src/index.ts 公共 re-export 面）。
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { fakeManagerCtx } from "../helpers.ts";

// I8 判定（S6 实测回退）：本文件构造 McpManager，而编排子层端口表只在包根组合根
// （src/index.ts 顶层 installOrchestrator）装配、且重复装配当场抛错——直引域门面会跳过装配、
// 构造即红（实测 exit 1）。故保留包根导入（基线 unitImportFaceViolations 条目保留）；
// 把组合根装配搬进门面属运行时改动，越界（见遗留）。
// S6-B2：McpManager 构造是装配依赖，留包根（理由见上）；其余纯符号改道域门面。
const { McpManager } = await import("../../src/index.ts");
const { McpStore } = await import("../../src/server/store/interface.ts");
const { makeResolveRoot, normalizeScope } = await import("../../src/server/workspace/interface.ts");
const { normalizeServer } = await import("../../src/server/config/interface.ts");
const { MIDDLEWARE_GLOBAL_ROOT, SCOPE_GLOBAL, SCOPE_PROJECT } =
  await import("../../src/shared/interface.ts");

describe("normalizeScope（#767 S1-5c 自 unit-transport.test.ts 迁入）", () => {
  it("project → SCOPE_PROJECT", () => {
    expect(normalizeScope("project")).toBe(SCOPE_PROJECT);
  });

  it("global → SCOPE_GLOBAL", () => {
    expect(normalizeScope("global")).toBe(SCOPE_GLOBAL);
  });

  it("空串 → SCOPE_GLOBAL", () => {
    expect(normalizeScope("")).toBe(SCOPE_GLOBAL);
  });

  it("大小写敏感回落 global", () => {
    expect(normalizeScope("PROJECT")).toBe(SCOPE_GLOBAL);
  });

  it("未知值回落 global", () => {
    expect(normalizeScope("whatever")).toBe(SCOPE_GLOBAL);
  });
});

describe("makeResolveRoot 基本路由（迁移自 apply-runtime.ts，行为不变）", () => {
  let dir: string;
  let resolveRoot: (agent: unknown) => Promise<string | undefined>;

  beforeAll(() => {
    dir = mkdtempSync(join(tmpdir(), "dsh-mcp-ws-"));
    const store = new McpStore(join(dir, "global.json"));
    store.data = { version: 1, servers: [] };
    const manager = new McpManager(fakeManagerCtx(), store);
    resolveRoot = makeResolveRoot(manager);
  });

  afterAll(() => {
    rmSync(dir, { recursive: true, force: true });
  });

  it("agent-less 返回 undefined", async () => {
    expect(await resolveRoot(null)).toBeUndefined();
  });

  it("cwd 归一化项目根优先（不回落 @global）", async () => {
    expect(await resolveRoot({ session: { header: { cwd: "/proj" } } })).toBe("/proj");
  });
});

// B3 红测：空 cwd 回落 @global 含 runtime 源 ----
// 现状：makeResolveRoot 回落只查 globalServers()=store.data.servers（manager.ts
// L269），不含 runtimeRegistry 注入服务器 → 仅 runtime 服务器（codegraph 等）时
// 回落 undefined（「无法确定工作空间」）；修复（requirements 8.1 纠偏）：改查
// projectServersFor("@global")（含 runtime 并集）。
// #767 笔 1a：这道回落**去掉了 all 条件**（可达性三件套之二）——本组判据与模式无关。
describe("B3 / #767 笔 1a：空 cwd 无条件回落 @global（含 runtime 源）", () => {
  let dir: string;
  let resolveRoot: (agent: unknown) => Promise<string | undefined>;

  beforeAll(() => {
    dir = mkdtempSync(join(tmpdir(), "dsh-mcp-ws-b3-"));
    const store = new McpStore(join(dir, "global.json"));
    store.data = { version: 1, servers: [] }; // 无 store 全局服务器（仅 runtime 注入）
    const manager = new McpManager(fakeManagerCtx(), store);
    // codegraph 等 runtime 注入服务器不落 store，只进 runtimeRegistry（#413）。
    manager.runtimeRegistry.set(
      "cg",
      normalizeServer({ name: "cg", transport: "stdio", command: "dsh-noop-cmd" }),
    );
    resolveRoot = makeResolveRoot(manager);
  });

  afterAll(() => {
    rmSync(dir, { recursive: true, force: true });
  });

  it("B3：空 cwd 回落 @global 含 runtime 源", async () => {
    // 会话无 cwd（空 cwd）→ 回落应含 runtime 源 → @global（无条件，不再看模式）。
    const root = await resolveRoot({ session: { header: {} } });
    expect(root).toBe(MIDDLEWARE_GLOBAL_ROOT);
  });
});

