/**
 * 官方 MCP 客户端包名的导入面锁（#767 S1-4c；设计 §6.4-2 的静态断言落地）。
 *
 * 判据：本包对 `@deepseek-ai/dsh-mcp-client` 的**唯一**合规接触面是「运行时按包名解析」——
 * loader 的 `import(说明符)` 调用，而说明符取自 server/shared/constants.ts 的那一个常量。
 * 该包不在 pnpm catalog、仓库内不可解析（实测 require.resolve → MODULE_NOT_FOUND），任何
 * 编译期 import / require / 字面量动态 import 都会让 tsc 解析失败、或在打包期被 esbuild 当
 * 本地依赖内联（发布物里就多出一份官方客户端的副本）。
 *
 * 为什么还要一条测试：那两种失败都要等到 CI 或用户机上才现形；这条在改动当刻就判红。契约面
 * 另有 pnpm-workspace.yaml 的「仅限 import type」与 contract-check 兜住，本测试是更早的一道。
 *
 * 判据面刻意只含 src 与 test：草稿区（.maintenance-drafts/）里的真机尖刺本来就要按包名 import。
 */
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const pkgDir = fileURLToPath(new URL("../../", import.meta.url));
const SPECIFIER = "@deepseek-ai/dsh-mcp-client";

/** 参与判据的文件（.ts/.tsx；.d.ts 无值面）。 */
function collectFiles(root: string): string[] {
  const out: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const abs = join(dir, entry.name);
      if (entry.isDirectory()) walk(abs);
      else if (/\.tsx?$/.test(entry.name) && !entry.name.endsWith(".d.ts")) out.push(abs);
    }
  };
  walk(root);
  return out.sort();
}

/** 包根相对路径（判词里稳定可读）。 */
function rel(abs: string): string {
  return abs.slice(pkgDir.length).replace(/\\/g, "/");
}

/** 逐行命中（行号 + 内容）；global 正则每次重置 lastIndex。 */
function hits(text: string, re: RegExp): string[] {
  const found: string[] = [];
  text.split("\n").forEach((line: string, index: number) => {
    re.lastIndex = 0;
    if (re.test(line)) found.push(`${index + 1}: ${line.trim()}`);
  });
  return found;
}

const SRC_FILES = collectFiles(join(pkgDir, "src"));
const TEST_FILES = collectFiles(join(pkgDir, "test"));
const ALL_FILES = [...SRC_FILES, ...TEST_FILES];

describe("官方 dsh-mcp-client 的导入面锁", () => {
  it("src / test 里没有任何对官方包的编译期 import（含 import type）", () => {
    const re = new RegExp(`from\\s+["']${SPECIFIER}["']`, "g");
    const found = ALL_FILES.filter((f) => hits(readFileSync(f, "utf8"), re).length > 0).map(rel);
    expect(found, "官方包不在 catalog：编译期 import 会让 tsc 直接解析失败").toEqual([]);
  });

  it("src / test 里没有 require(...) / 字面量动态 import(...) / 副作用 import", () => {
    // 副作用形态（`import "…"`）既没有 from 也没有括号，前一条判据与它不相交——漏了它，
    // 「只在 constants.ts 保留一处字面量」这条也就被绕过了。
    const forms = [
      new RegExp(`require\\(\\s*["']${SPECIFIER}["']`, "g"),
      new RegExp(`import\\(\\s*["']${SPECIFIER}["']`, "g"),
      new RegExp(`import\\s+["']${SPECIFIER}["']`, "g"),
    ];
    const found = ALL_FILES.flatMap((f) => {
      const text = readFileSync(f, "utf8");
      return forms.flatMap((re) => hits(text, re).map((h) => `${rel(f)} ${h}`));
    });
    expect(found, "按包名解析只许经 loader 的 import(说明符)，说明符取自共享层常量").toEqual([]);
  });

  it("包名字面量在 src 里只有一处物理定义，且落在 server/shared/constants.ts", () => {
    const re = new RegExp(`["']${SPECIFIER}["']`, "g");
    const found = SRC_FILES.flatMap((f) =>
      hits(readFileSync(f, "utf8"), re).map((h) => `${rel(f)} ${h}`),
    );
    expect(found).toHaveLength(1);
    expect(found[0]).toContain("src/server/shared/constants.ts");
  });

  it("没有对 @deepseek-ai/cordis-plugin-loader 的 import（不在 catalog，类型面取不到）", () => {
    const re = /from\s+["']@deepseek-ai\/cordis-plugin-loader["']/g;
    const found = ALL_FILES.filter((f) => hits(readFileSync(f, "utf8"), re).length > 0).map(rel);
    expect(found, "loader 服务的形状由 server/shared/host-faces.ts 自持声明").toEqual([]);
  });
});

/**
 * dsh-mcp-manager — unit：同路径写串行（R11 的指定用例）。
 *
 * 并发同路径的可判定判据只有「后写者的内容留在盘上」，而两次 rename 的先后在真实文件系统上
 * 由调度决定。这里只拦 `writeFile` 的**一拍**：第一次写挂起不返回，第二次写若越过队列就会
 * 自己跑完 writeFile + rename。挂起放行后，盘上留下的即后写者（有队列）/ 先写者（无队列）
 * ——去掉队列这条用例必然判红，不是装饰。除这一拍外，mkdir / writeFile / rename / 读取都是
 * 真实文件系统。
 */
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { configFile, writeFileAtomic } from "../../src/server/shared/interface.ts";

/** 挂起闸门：state.held 为真时，下一次 writeFile 等 release() 放行。 */
const gate = vi.hoisted(() => {
  const state = { calls: 0, held: false, release: (): void => {} };
  const released = new Promise<void>((resolve) => {
    state.release = resolve;
  });
  return { state, released };
});

vi.mock("node:fs/promises", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:fs/promises")>();
  return {
    ...actual,
    writeFile: async (...args: Parameters<typeof actual.writeFile>) => {
      gate.state.calls += 1;
      if (gate.state.held) {
        gate.state.held = false;
        await gate.released;
      }
      return actual.writeFile(...args);
    },
  };
});

/** 轮询直到谓词为真；用于等「第一次 writeFile 已被调用」。 */
async function waitFor(predicate: () => boolean, timeoutMs = 2000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (!predicate()) {
    if (Date.now() > deadline) throw new Error("等待 writeFile 调用超时");
    await new Promise((resolve) => setTimeout(resolve, 1));
  }
}

/** 谁先到算谁：写已完成，或等待窗口耗尽。 */
async function settleOrWait(pending: Promise<void>, ms: number): Promise<void> {
  await Promise.race([
    pending.then(
      () => undefined,
      () => undefined,
    ),
    new Promise<void>((resolve) => setTimeout(resolve, ms)),
  ]);
}

describe("同路径并发写", () => {
  let home: string;
  let previousHome: string | undefined;

  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "dsh-mcp-queue-"));
    previousHome = process.env.DSH_HOME;
    process.env.DSH_HOME = home;
    gate.state.calls = 0;
    gate.state.held = false;
  });

  afterEach(() => {
    if (previousHome === undefined) delete process.env.DSH_HOME;
    else process.env.DSH_HOME = previousHome;
    rmSync(home, { recursive: true, force: true });
  });

  it("两次并发写同一路径，盘上留下的是后写者", async () => {
    const target = configFile();
    gate.state.held = true;
    const first = writeFileAtomic(target, "first");
    await waitFor(() => gate.state.calls === 1);
    const second = writeFileAtomic(target, "second");
    // 有队列：second 排在 first 之后，这里只会等满窗口；无队列：second 当场写完 rename。
    await settleOrWait(second, 300);
    gate.state.release();
    await Promise.all([first, second]);
    expect(readFileSync(target, "utf8")).toBe("second");
  });
});

/**
 * dsh-mcp-manager — unit：initMiddleware 失败语义（#392 遗留⑤）。
 *
 * 锁定的契约：configStore 加载抛错时 initMiddleware 重置 maps 后重抛——
 * 不静默吞错（apply 中止），this.middleware 保持未赋值（不建半初始化实例）。
 * 真实 load 实现损坏/缺失恒回空、永不抛，故用毒化 configStore 覆盖该 catch 分支。
 * 本文件独占模块图：installOrchestrator 在此装配毒化端口，不影响其它用例文件。
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import type { Context } from "@deepseek-ai/cordis";
import { installOrchestrator } from "../../src/server/connection/orchestrator/interface.ts";
import { McpManager } from "../../src/server/connection/orchestrator/manager.ts";
import * as catalogApi from "../../src/server/catalog/interface.ts";
import * as configModelApi from "../../src/server/config/interface.ts";
import * as lifecycleApi from "../../src/server/servers/lifecycle/interface.ts";
import * as pipelineApi from "../../src/server/pipeline/interface.ts";
import * as runtimeApi from "../../src/server/connection/runtime/interface.ts";
import * as statsApi from "../../src/server/stats/interface.ts";
import * as storeApi from "../../src/server/store/interface.ts";
import * as upgradeApi from "../../src/server/upgrade/interface.ts";
import * as workspaceApi from "../../src/server/workspace/interface.ts";
import { McpStore } from "../../src/server/store/interface.ts";

describe("#392 遗留⑤：initMiddleware 加载失败穿透且不残留半初始化状态", () => {
  it("configStore 抛错时重抛、maps 置空、middleware 保持未赋值", async () => {
    const boom = new Error("dsh-mcp-manager: poisoned configStore load");
    // 除加载面外全用真实实现：断言只针对 catch 的重置+重抛语义。
    installOrchestrator({
      catalog: catalogApi,
      configModel: configModelApi,
      configStore: {
        ...storeApi,
        loadUserState: async () => {
          throw boom;
        },
        loadDisabledTools: async () => {
          throw boom;
        },
      },
      runtime: runtimeApi,
      lifecycle: lifecycleApi,
      pipeline: pipelineApi,
      stats: statsApi,
      workspace: workspaceApi,
      upgrade: upgradeApi,
    });
    const dir = mkdtempSync(join(tmpdir(), "dsh-mcp-initfail-"));
    try {
      const store = new McpStore(join(dir, "global.json"));
      store.data = { version: 1, servers: [] };
      const manager = new McpManager(
        {
          logger: {
            info: () => {},
            warn: () => {},
            error: () => {},
          },
        } as unknown as Context,
        store,
      );
      // 失败不吞错：原样穿透给 apply（apply 无 catch，中止装配）。
      await expect(manager.initMiddleware()).rejects.toBe(boom);
      // 半初始化状态已清理：实例未建、两表置空。
      expect(manager.middleware).toBeUndefined();
